package io.knowledgebrain.integration;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.integration.githubwork.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_INTEGRATION_DATABASE_URL",matches=".+")
class GitHubWorkStoreIntegrationTest extends GitHubWorkFixtures {
 @Test void explicitImportsArePrivateIndependentOfCommitVersionAndExactReplayKeepsReceipt()throws Exception{var parent=f.store.get(f.space,repo);var input=batch("ISSUE",item(1,"ISSUE","OPEN","First <img>","2020-01-02T00:00:00Z"));String key=f.key();assertEquals(0,work.state(f.space,repo,"ISSUE").version());var first=sync("ISSUE",key,0,input);assertEquals(1,first.sync().importedCount());assertEquals(1,first.state().version());var value=work.page(f.space,repo,"ISSUE","ALL",null,20).items().getFirst();assertEquals(7,value.itemId().version());assertEquals("PRIVATE",value.visibility());assertEquals("PUBLIC",value.sourceVisibility());assertNull(value.draft());assertEquals(f.actor,value.observedBy());assertEquals(parent,f.store.get(f.space,repo));assertTrue(f.store.commits(f.space,repo,null,20).items().isEmpty());var second=sync("ISSUE",f.key(),1,input);assertEquals(1,second.sync().unchangedCount());assertEquals(0,second.sync().updatedCount());assertEquals(value,work.get(f.space,repo,value.itemId()));assertEquals(1,events());var replay=work.replay(f.space,repo,"ISSUE",f.actor,key,0);assertTrue(replay.replay());assertEquals(first.sync(),replay.sync());assertEquals(2,replay.state().version());f.status(409,()->work.replay(f.space,repo,"ISSUE",f.actor,key,1));var history=work.history(f.space,repo,value.itemId(),Long.MAX_VALUE,5);assertEquals(value,history.getFirst().snapshot());var wire=GitHubWorkEventEnvelopeV1.parseFrom(f.sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,value.itemId()));assertEquals("GitHubWorkItemImported",wire.getEventType());var payload=GitHubWorkItemObservedV1.parseFrom(wire.getPayload());assertEquals("ISSUE",payload.getKind());assertFalse(payload.hasDraft());assertEquals(value.itemId().toString(),payload.getItemId());}
 @Test void changedSourceAppendsImmutableVersionAndOlderSourceCannotOverwrite(){sync("PULL_REQUEST",f.key(),0,batch("PULL_REQUEST",item(2,"PULL_REQUEST","OPEN","Old title","2020-01-02T00:00:00Z")));var old=work.page(f.space,repo,"PULL_REQUEST","OPEN",null,20).items().getFirst();var result=sync("PULL_REQUEST",f.key(),1,batch("PULL_REQUEST",item(2,"PULL_REQUEST","CLOSED","New title","2020-01-03T00:00:00Z")));assertEquals(1,result.sync().updatedCount());var fresh=work.get(f.space,repo,old.itemId());assertEquals(2,fresh.version());assertEquals(old.firstObservedAt(),fresh.firstObservedAt());assertEquals(old,work.history(f.space,repo,old.itemId(),2,5).getFirst().snapshot());assertEquals(2,events());assertTrue(work.page(f.space,repo,"PULL_REQUEST","OPEN",null,20).items().isEmpty());f.status(409,()->sync("PULL_REQUEST",f.key(),2,batch("PULL_REQUEST",item(2,"PULL_REQUEST","OPEN","Stale","2020-01-02T00:00:00Z"))));assertEquals(fresh,work.get(f.space,repo,old.itemId()));assertEquals(2,work.state(f.space,repo,"PULL_REQUEST").version());assertEquals(2,events());}
 @Test void catalogsAndReceiptsUseScopedStableCursorsAndRetainMissingBoundedPageItems(){var rows=new ArrayList<GitHubWorkClient.Item>();for(int n=1;n<=20;n++)rows.add(item(n,"ISSUE",n%2==0?"OPEN":"CLOSED","Item "+n,"2020-01-02T00:00:00Z"));sync("ISSUE",f.key(),0,new GitHubWorkClient.Batch(f.source,"ISSUE",rows,20,true));sync("ISSUE",f.key(),1,batch("ISSUE",item(21,"ISSUE","OPEN","Next","2020-01-02T00:00:00Z"),item(22,"ISSUE","OPEN","Last","2020-01-02T00:00:00Z")));var page=work.page(f.space,repo,"ISSUE","ALL",null,20);assertEquals(20,page.items().size());assertEquals(2,work.page(f.space,repo,"ISSUE","ALL",page.nextAfter(),20).items().size());assertEquals(12,work.page(f.space,repo,"ISSUE","OPEN",null,100).items().size());assertTrue(work.page(f.space,repo,"PULL_REQUEST","ALL",null,100).items().isEmpty());sync("ISSUE",f.key(),2,batch("ISSUE"));assertEquals(22,work.page(f.space,repo,"ISSUE","ALL",null,100).items().size());var receipts=work.syncs(f.space,repo,"ISSUE",null,1);assertEquals(3,receipts.items().getFirst().syncVersion());assertEquals(0,receipts.items().getFirst().observedCount());assertEquals(2,work.syncs(f.space,repo,"ISSUE",receipts.nextBefore(),20).items().size());f.status(400,()->work.page(f.space,repo,"ISSUE","RETIRED",null,20));f.status(400,()->work.page(f.space,repo,"ISSUE","ALL",null,101));f.status(404,()->work.page(f.ids.next(),repo,"ISSUE","ALL",null,20));}
 @Test void disconnectedSourceRetainsReadsAndExactRetryButRejectsNewCommand(){String key=f.key();var input=batch("ISSUE",item(1,"ISSUE","OPEN","Retained","2020-01-02T00:00:00Z"));var original=sync("ISSUE",key,0,input);f.store.disconnect(f.space,repo,f.actor,1,f.trace);assertEquals("RETIRED",work.state(f.space,repo,"ISSUE").repositoryState());assertEquals(original.sync(),sync("ISSUE",key,0,input).sync());assertEquals(1,work.page(f.space,repo,"ISSUE","ALL",null,20).items().size());f.status(409,()->sync("ISSUE",f.key(),1,input));assertEquals(1,events());f.status(412,()->sync("PULL_REQUEST",f.key(),1,batch("PULL_REQUEST")));}
 @Test void concurrentSameIntentReplaysOnceAndIndependentKindsNeverShareCas()throws Exception{var input=batch("ISSUE",item(1,"ISSUE","OPEN","Concurrent","2020-01-02T00:00:00Z"));String key=f.key();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->sync("ISSUE",key,0,input));var b=pool.submit(()->sync("ISSUE",key,0,input));var x=a.get();var y=b.get();assertNotEquals(x.replay(),y.replay());assertEquals(x.sync(),y.sync());}assertEquals(1,events());assertEquals(1,work.state(f.space,repo,"ISSUE").version());assertEquals(0,work.state(f.space,repo,"PULL_REQUEST").version());sync("PULL_REQUEST",key,0,batch("PULL_REQUEST",item(2,"PULL_REQUEST","OPEN","PR","2020-01-02T00:00:00Z")));assertEquals(2,events());assertEquals(1,f.store.get(f.space,repo).version());}
 @Test void invalidMixedBatchOrRepoIdentityRollsBackAllFactsAndReceipts(){var bad=new GitHubWorkClient.Batch(new GitHubClient.Repository("42",f.source.fullName(),f.source.url(),"main"),"ISSUE",List.of(),0,false);f.status(409,()->sync("ISSUE",f.key(),0,bad));var valid=item(1,"ISSUE","OPEN","Valid","2020-01-02T00:00:00Z");var duplicate=item(1,"ISSUE","OPEN","Duplicate","2020-01-02T00:00:00Z");f.status(409,()->sync("ISSUE",f.key(),0,batch("ISSUE",valid,duplicate)));assertEquals(0,events());assertEquals(0,work.state(f.space,repo,"ISSUE").version());assertTrue(work.page(f.space,repo,"ISSUE","ALL",null,20).items().isEmpty());assertTrue(work.syncs(f.space,repo,"ISSUE",null,20).items().isEmpty());}
}
